import React from 'react';

import { formatDistance } from '@helpers/formatHelper';
import PohAva from '@ui-kit/Ava';
import PohBadge, { BadgeVariant } from '@ui-kit/Badge/Badge';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';

import { IWorkoutFullInvite } from '../@types/workoutsInvites.types';

interface IWorkoutInviteListItemProps {
  invite: IWorkoutFullInvite;
}

const WorkoutInviteListItem: React.FC<IWorkoutInviteListItemProps> = ({ invite }) => {
  return (
    <PohRow>
      <PohCol sm={8}>
        <h5 className="mb-0">{invite.workout.name}</h5>
        <small>
          <PohBadge variant={BadgeVariant.Success}>
            {formatDistance(invite.track.distance)}
          </PohBadge>
          &nbsp;
          {invite.workout.type.name}
          &nbsp;
          {invite.track.start.toLocaleString()} – {invite.track.finish.toLocaleTimeString()}
        </small>
      </PohCol>
      <PohCol sm={4} className="d-flex align-items-center justify-content-end">
        <div className="text-end me-2" style={{ lineHeight: 1.2 }}>
          <small className="d-block">Приглашение от:</small>
          <small className="d-block">
            <strong>
              {invite.author.name} {invite.author.surname}
            </strong>
          </small>
          <small className="d-block text-muted">{invite.created_at.toLocaleString()}</small>
        </div>
        <PohAva src={invite.author.photo} alt={invite.author.name} />
      </PohCol>
    </PohRow>
  );
};

export default WorkoutInviteListItem;
