import React from 'react';

import { useNavigate } from 'react-router-dom';

import PageLoader from '@components/PageLoader';
import Breadcrumb from '@ui-kit/Breadcrumb';
import Empty from '@ui-kit/Empty';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';
import PohList from '@ui-kit/List';

import WorkoutInviteListItem from './WorkoutInviteListItem';
import { getWorkoutInvitesForCurrentUser } from '../@services/workoutsInvites.service';
import { IWorkoutFullInvite } from '../@types/workoutsInvites.types';

interface IWorkoutsInvitesProps {}

const WorkoutsInvites: React.FC<IWorkoutsInvitesProps> = () => {
  const [data, setData] = React.useState<IWorkoutFullInvite[]>([]);
  const [isLoading, setIsLoading] = React.useState(true);
  const navigate = useNavigate();
  React.useEffect(() => {
    getWorkoutInvitesForCurrentUser()
      .then(setData)
      .finally(() => setIsLoading(false));
  }, []);

  return (
    <section>
      <>
        <Breadcrumb
          data={[
            { href: `/workouts`, text: 'Тренировки' },
            { href: `/workouts/invites`, text: 'Приглашения', active: true },
          ]}
        />
        <PohContainer>
          <PohRow>
            <PohCol sm={12}>
              <h3 className="mb-3">Приглашения в тренировки</h3>
            </PohCol>
          </PohRow>
          <PohRow>
            <PohCol sm={12}>
              {isLoading && <PageLoader />}
              {!data.length && <Empty>Пока нет приглашений</Empty>}
              {data.length > 0 && (
                <PohList
                  data={data.map((d) => {
                    return {
                      key: d.id,
                      children: <WorkoutInviteListItem invite={d} />,
                      action: true,
                      onClick: () => navigate(`/workouts/${d.workout.id}`),
                    };
                  })}
                />
              )}
            </PohCol>
          </PohRow>
        </PohContainer>
      </>
    </section>
  );
};

export default WorkoutsInvites;
